1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Derives an owner's {@code identityKey} — the single value all duplicate detection is expressed
12	 * through.
13	 *
14	 * <p>The key is {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. Two owners
15	 * are duplicates only when their <em>whole</em> keys are equal (see {@link CheckIdentityUnique}).
16	 * Because the telephone is part of the key, two members of the same household (same
17	 * {@code householdId}) with different telephones have different keys and are both allowed.
18	 *
19	 * <p>The three components are normalized so the key is stable: the telephone to E.164 form (see
20	 * {@link TelephoneE164}), the email lower-cased and trimmed, and a null household rendered as empty.
21	 */
22	public final class OwnerIdentity {
23	
24	    private OwnerIdentity() {
25	    }
26	
27	    /** The identity key of a persisted owner, from its stored telephone, email and householdId. */
28	    public static String of(Owner owner) {
29	        return key(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
30	    }
31	
32	    /** Assemble the identity key from the three components, normalizing telephone and email. */
33	    public static String key(String telephone, String email, String householdId) {
34	        return normalizeTelephone(telephone) + "|" + normalizeEmail(email) + "|"
35	                + (householdId == null ? "" : householdId);
36	    }
37	
38	    /**
39	     * The stable, shared household identifier for an owner's last name and postcode: the first 12
40	     * upper-case hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode} (last name
41	     * lower-cased with whitespace collapsed; postcode trimmed). Owners with the same last name and
42	     * postcode get the same value automatically, regardless of creation order, so the household is
43	     * keyed on {@code (lastName, postcode)}. Returns {@code null} when there is no postcode — an owner
44	     * without a postcode is not in any household.
45	     */
46	    public static String householdIdFor(String lastName, String postcode) {
47	        String normalizedPostcode = normalizePostcode(postcode);
48	        if (normalizedPostcode == null) {
49	            return null;
50	        }
51	        return sha256Hex(normalizeLastName(lastName) + "|" + normalizedPostcode, 12);
52	    }
53	
54	    /**
55	     * The HASH8 half of an owner's region-and-hash {@code customerCode}: the first 8 upper-case hex
56	     * characters of SHA-256 over {@code normalizedTelephone + lastName}. The telephone is normalized
57	     * to E.164 form (null/invalid becomes empty) so the hash is stable across equivalent phone
58	     * formats; the last name is taken as stored.
59	     */
60	    public static String customerCodeHash(String telephone, String lastName) {
61	        return sha256Hex(normalizeTelephone(telephone) + (lastName == null ? "" : lastName), 8);
62	    }
63	
64	    /** First {@code length} upper-case hex chars of SHA-256 over the UTF-8 bytes of {@code input}. */
65	    private static String sha256Hex(String input, int length) {
66	        try {
67	            byte[] digest = MessageDigest.getInstance("SHA-256")
68	                    .digest(input.getBytes(StandardCharsets.UTF_8));
69	            StringBuilder sb = new StringBuilder(64);
70	            for (byte b : digest) {
71	                sb.append(String.format("%02x", b));
72	            }
73	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
74	        }
75	        catch (NoSuchAlgorithmException e) {
76	            throw new IllegalStateException("SHA-256 not available", e);
77	        }
78	    }
79	
80	    /** Telephone in E.164 form for comparison; null/invalid becomes empty. */
81	    private static String normalizeTelephone(String telephone) {
82	        String e164 = TelephoneE164.normalize(telephone);
83	        return e164 == null ? "" : e164;
84	    }
85	
86	    /** Email lower-cased and trimmed so comparison ignores case; null/blank becomes empty. */
87	    private static String normalizeEmail(String email) {
88	        if (email == null) {
89	            return "";
90	        }
91	        return email.trim().toLowerCase(Locale.ROOT);
92	    }
93	
94	    /** Last name lower-cased with runs of whitespace collapsed, so comparison ignores case/spacing. */
95	    private static String normalizeLastName(String value) {
96	        if (value == null) {
97	            return "";
98	        }
99	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
100	    }
101	
102	    /** Postcode trimmed; null or blank becomes null (no household). */
103	    private static String normalizePostcode(String postcode) {
104	        if (postcode == null) {
105	            return null;
106	        }
107	        String trimmed = postcode.trim();
108	        return trimmed.isEmpty() ? null : trimmed;
109	    }
110	}
