1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.LinkedHashMap;
4	import java.util.Map;
5	import java.util.regex.Pattern;
6	
7	/**
8	 * Normalizes a telephone number to E.164 form.
9	 *
10	 * <p>Rules: strip spaces, dashes and brackets; keep a leading '+' and country code when
11	 * present, otherwise assume country code '+61' and drop a single leading '0' from the
12	 * national digits. The result is {@code '+'} followed by 8 to 15 digits; anything that
13	 * cannot form a valid E.164 number yields {@code null}.
14	 *
15	 * <p>The national number's length is validated against its country code: a {@code '+61'}
16	 * (Australia) number requires exactly 9 national digits and a {@code '+1'} (NANP) number
17	 * requires exactly 10; a number whose national part is the wrong length for its country
18	 * yields {@code null}.
19	 *
20	 * <p>Example: {@code "0412 345 678"} becomes {@code "+61412345678"}.
21	 */
22	public final class TelephoneE164 {
23	
24	    /** Characters removed before interpreting the number: spaces, dashes and brackets. */
25	    private static final Pattern SEPARATORS = Pattern.compile("[\\s\\-()]");
26	
27	    /**
28	     * Country code (without '+') to its required national-number length. Ordered
29	     * longest-prefix-first so a code such as {@code "61"} is matched before {@code "1"}.
30	     */
31	    private static final Map<String, Integer> NATIONAL_LENGTHS = new LinkedHashMap<>();
32	
33	    static {
34	        NATIONAL_LENGTHS.put("61", 9);
35	        NATIONAL_LENGTHS.put("1", 10);
36	    }
37	
38	    private TelephoneE164() {
39	    }
40	
41	    /**
42	     * Convert to E.164, or return {@code null} when the input cannot form a valid number.
43	     */
44	    static String normalize(String raw) {
45	        if (raw == null) {
46	            return null;
47	        }
48	        String trimmed = raw.trim();
49	        boolean hasCountryCode = trimmed.startsWith("+");
50	        String cleaned = SEPARATORS.matcher(trimmed).replaceAll("");
51	        String digits;
52	        if (hasCountryCode) {
53	            // Keep the given country code; the '+' is re-added below.
54	            digits = cleaned.substring(1);
55	        }
56	        else {
57	            // No country code: assume '+61' and drop a single leading national '0'.
58	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
59	            digits = "61" + national;
60	        }
61	        if (!digits.chars().allMatch(Character::isDigit) || digits.isEmpty()) {
62	            return null;
63	        }
64	        if (digits.length() < 8 || digits.length() > 15) {
65	            return null;
66	        }
67	        // Validate the national-number length against the country code (e.g. '+61' => 9
68	        // national digits, '+1' => 10). Codes are checked longest-prefix-first.
69	        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTHS.entrySet()) {
70	            String code = entry.getKey();
71	            if (digits.startsWith(code)) {
72	                int nationalLength = digits.length() - code.length();
73	                if (nationalLength != entry.getValue()) {
74	                    return null;
75	                }
76	                break;
77	            }
78	        }
79	        return "+" + digits;
80	    }
81	
82	    /**
83	     * Format a stored E.164 number for humans: the country code, a space, then the national
84	     * digits grouped in threes (e.g. {@code "+61412345678"} becomes {@code "+61 412 345 678"}).
85	     *
86	     * <p>The country code is identified longest-prefix-first from the known codes; an unknown
87	     * code falls back to its first two digits. Anything that is not an E.164 number (no leading
88	     * {@code '+'} or non-digit body) is returned unchanged.
89	     */
90	    public static String display(String e164) {
91	        if (e164 == null || !e164.startsWith("+")) {
92	            return e164;
93	        }
94	        String digits = e164.substring(1);
95	        if (digits.isEmpty() || !digits.chars().allMatch(Character::isDigit)) {
96	            return e164;
97	        }
98	        String code = null;
99	        for (String candidate : NATIONAL_LENGTHS.keySet()) {
100	            if (digits.startsWith(candidate)) {
101	                code = candidate;
102	                break;
103	            }
104	        }
105	        if (code == null) {
106	            code = digits.length() > 2 ? digits.substring(0, 2) : digits;
107	        }
108	        String national = digits.substring(code.length());
109	        if (national.isEmpty()) {
110	            return "+" + code;
111	        }
112	        StringBuilder grouped = new StringBuilder();
113	        for (int i = 0; i < national.length(); i++) {
114	            if (i > 0 && i % 3 == 0) {
115	                grouped.append(' ');
116	            }
117	            grouped.append(national.charAt(i));
118	        }
119	        return "+" + code + " " + grouped;
120	    }
121	}
