1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	import java.util.Set;
6	import java.util.regex.Pattern;
7	
8	import net.officefloor.plugin.variable.Out;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.escalation.DisposableEmailDomainException;
11	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
12	import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
13	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
14	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
15	import org.springframework.web.bind.annotation.RequestBody;
16	
17	/**
18	 * Binds the owner body and rejects it when any required field is missing or blank, so an
19	 * invalid body is a 400 (listing the offending field names) even when the owner does not exist.
20	 * Also normalizes the telephone to E.164 form (see {@link TelephoneE164}), publishing the
21	 * normalized value so it is stored and returned as {@code telephone}.
22	 * The address is normalized (see {@link AddressNormalizer}) before the required-field check, so a
23	 * value that is blank only after normalization is rejected, and the normalized form is stored and
24	 * returned as {@code address}.
25	 * The optional email is accepted when absent; when present it must be a syntactically valid
26	 * address (else 400) whose domain is not on the disposable-domain blocklist (else 400), and is
27	 * lower-cased so it is stored and returned as {@code email}.
28	 * Runs before {@link LoadOwner}/{@link BuildOwner} and publishes the body for later steps.
29	 */
30	public class ValidateOwner {
31	
32	    /** Syntactic email check: a non-empty local part, an '@', then a dotted domain. */
33	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s.]+(\\.[^@\\s.]+)+$");
34	
35	    /** A valid postcode is exactly four digits. */
36	    private static final Pattern POSTCODE = Pattern.compile("^[0-9]{4}$");
37	
38	    /** Disposable email domains that are never accepted, even when syntactically valid. */
39	    private static final Set<String> DISPOSABLE_DOMAINS =
40	            Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
41	
42	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
43	            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException,
44	            DisposableEmailDomainException, InvalidPostcodeException {
45	        List<String> missing = new ArrayList<>();
46	        if (isBlank(request.getFirstName())) {
47	            missing.add("firstName");
48	        }
49	        if (isBlank(request.getLastName())) {
50	            missing.add("lastName");
51	        }
52	        // Normalize whichever address fields are supplied (see AddressNormalizer). The structured
53	        // form (addressLine1 + optional addressLine2) is preferred; the flat 'address' input remains
54	        // accepted for backward compatibility. Normalizing before the required-field check means a
55	        // value that is blank only after normalization is rejected. An owner is valid when it
56	        // supplies an address in EITHER form: a non-blank addressLine1, or the flat address.
57	        String addressLine1 = AddressNormalizer.normalize(request.getAddressLine1());
58	        String addressLine2 = AddressNormalizer.normalize(request.getAddressLine2());
59	        String flatAddress = AddressNormalizer.normalize(request.getAddress());
60	        request.setAddressLine1(addressLine1.isEmpty() ? null : addressLine1);
61	        request.setAddressLine2(addressLine2.isEmpty() ? null : addressLine2);
62	        // The stored/returned 'address' is the composed structured address when addressLine1 is
63	        // present (normalized addressLine1, plus a single space and addressLine2 when present),
64	        // otherwise the normalized flat address.
65	        String address = !addressLine1.isEmpty()
66	                ? AddressNormalizer.compose(addressLine1, addressLine2)
67	                : flatAddress;
68	        request.setAddress(address);
69	        if (isBlank(address)) {
70	            missing.add("address");
71	        }
72	        if (isBlank(request.getCity())) {
73	            missing.add("city");
74	        }
75	        if (isBlank(request.getTelephone())) {
76	            missing.add("telephone");
77	        }
78	        if (!missing.isEmpty()) {
79	            throw new MissingOwnerFieldsException(missing);
80	        }
81	        // Normalize telephone to E.164; reject anything that cannot form a valid number.
82	        String e164 = TelephoneE164.normalize(request.getTelephone());
83	        if (e164 == null) {
84	            throw new InvalidTelephoneException(request.getTelephone());
85	        }
86	        request.setTelephone(e164);
87	        // Email is optional. When present it must be syntactically valid; store it lower-cased.
88	        String email = request.getEmail();
89	        if (email != null && !email.isBlank()) {
90	            String normalized = email.trim().toLowerCase();
91	            if (!EMAIL.matcher(normalized).matches()) {
92	                throw new InvalidEmailException(email);
93	            }
94	            // Reject syntactically valid addresses whose domain is a known disposable provider.
95	            String domain = normalized.substring(normalized.indexOf('@') + 1);
96	            if (DISPOSABLE_DOMAINS.contains(domain)) {
97	                throw new DisposableEmailDomainException(email);
98	            }
99	            request.setEmail(normalized);
100	        }
101	        // Postcode is optional. When present it must be four digits and, when the city maps to a
102	        // known region, fall within that region's range; a city with no known region accepts any
103	        // 4-digit postcode. The (trimmed) value is stored and returned as given.
104	        String postcode = request.getPostcode();
105	        if (postcode != null && !postcode.isBlank()) {
106	            String trimmed = postcode.trim();
107	            if (!POSTCODE.matcher(trimmed).matches()) {
108	                throw new InvalidPostcodeException(postcode);
109	            }
110	            int[] range = CityRegion.postcodeRangeOf(request.getCity());
111	            if (range != null) {
112	                int value = Integer.parseInt(trimmed);
113	                if (value < range[0] || value > range[1]) {
114	                    throw new InvalidPostcodeException(postcode);
115	                }
116	            }
117	            request.setPostcode(trimmed);
118	        }
119	        validated.set(request);
120	    }
121	
122	    private static boolean isBlank(String value) {
123	        return value == null || value.isBlank();
124	    }
125	}
