1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Detects a <em>soft</em> duplicate: an existing owner that shares this owner's {@code lastName}
10	 * (compared case-insensitively) and {@code postcode} but has a <em>different</em> telephone.
11	 *
12	 * <p>Such an owner is deliberately still created — unlike a hard duplicate, whose whole identity key
13	 * matches an existing owner's and is rejected with 409 (see {@link CheckIdentityUnique}). Because the
14	 * telephone differs, the identity keys differ too, so a soft match is never also a hard duplicate.
15	 *
16	 * <p>The response surfaces the match through {@code possibleDuplicate} / {@code possibleDuplicateOf}.
17	 * The earliest (lowest id) matching owner is reported so the result is stable.
18	 *
19	 * <p>A <em>declared household member</em> — an owner that shares its {@code householdId} with another
20	 * owner, created by opting in with {@code sharesHousehold} — is never a suspect: sharing a last name
21	 * and postcode now makes owners the same household, so the only way such an owner is created at all is
22	 * as a declared member. Callers suppress the flag for them via {@link #sharesHousehold}.
23	 */
24	public final class PossibleDuplicate {
25	
26	    private PossibleDuplicate() {
27	    }
28	
29	    /**
30	     * Whether {@code owner} is a declared household member: it shares its (non-null) {@code householdId}
31	     * with another owner. Such an owner is not a suspected duplicate and is not flagged.
32	     */
33	    public static boolean sharesHousehold(Owner owner, OwnerRepository ownerRepository) {
34	        String householdId = owner.getHouseholdId();
35	        if (householdId == null || householdId.isBlank()) {
36	            return false;
37	        }
38	        for (Owner other : ownerRepository.findAll()) {
39	            if (other.getId() == null || other.getId().equals(owner.getId())) {
40	                continue;
41	            }
42	            if (householdId.equals(other.getHouseholdId())) {
43	                return true;
44	            }
45	        }
46	        return false;
47	    }
48	
49	    /**
50	     * The id of an existing owner sharing {@code owner}'s last name and postcode but with a
51	     * different telephone, or {@code null} when there is no such match (including when the owner has
52	     * no postcode).
53	     */
54	    public static Integer matchFor(Owner owner, OwnerRepository ownerRepository) {
55	        String postcode = normalizePostcode(owner.getPostcode());
56	        if (postcode == null) {
57	            return null;
58	        }
59	        String lastName = normalizeLastName(owner.getLastName());
60	        String telephone = normalizeTelephone(owner.getTelephone());
61	        Integer match = null;
62	        for (Owner other : ownerRepository.findAll()) {
63	            if (other.getId() == null || other.getId().equals(owner.getId())) {
64	                continue;
65	            }
66	            if (!postcode.equals(normalizePostcode(other.getPostcode()))) {
67	                continue;
68	            }
69	            if (!lastName.equals(normalizeLastName(other.getLastName()))) {
70	                continue;
71	            }
72	            if (telephone.equals(normalizeTelephone(other.getTelephone()))) {
73	                continue; // same telephone is not a soft match (and would be a hard duplicate)
74	            }
75	            if (match == null || other.getId() < match) {
76	                match = other.getId();
77	            }
78	        }
79	        return match;
80	    }
81	
82	    private static String normalizePostcode(String postcode) {
83	        if (postcode == null) {
84	            return null;
85	        }
86	        String trimmed = postcode.trim();
87	        return trimmed.isEmpty() ? null : trimmed;
88	    }
89	
90	    private static String normalizeLastName(String value) {
91	        if (value == null) {
92	            return "";
93	        }
94	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
95	    }
96	
97	    private static String normalizeTelephone(String telephone) {
98	        String e164 = TelephoneE164.normalize(telephone);
99	        return e164 == null ? "" : e164;
100	    }
