9	/**
10	 * Rejects creating an owner that duplicates an existing one, so the create endpoint responds 409
11	 * instead of storing a duplicate. Two rules, both keyed off the deterministic household:
12	 *
13	 * <ul>
14	 *   <li><strong>Exact identity duplicate</strong> — the new owner's whole identity key
15	 *       ({@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}, see
16	 *       {@link OwnerIdentity}) equals an existing owner's. This is genuinely the same person and is
17	 *       always rejected.</li>
18	 *   <li><strong>Household duplicate</strong> — the new owner shares an existing owner's household,
19	 *       i.e. the same {@code householdId} computed from {@code (lastName, postcode)}. Because the
20	 *       household is now keyed on {@code (lastName, postcode)}, a second owner with the same last name
21	 *       and postcode is the same household and is rejected — <em>unless</em> the request opts in with
22	 *       {@code sharesHousehold: true}, which bypasses this block so the owner is created as a declared
23	 *       household member.</li>
24	 * </ul>
25	 *
26	 * <p>An owner without a postcode has no household ({@code householdId} is null), so only the exact
27	 * identity rule applies to it.
28	 *
29	 * <p>Runs after {@link ValidateOwner} (which normalizes and publishes the body) and before
30	 * {@link BuildOwner}, comparing against every existing owner.
31	 */
32	public class CheckIdentityUnique {
33	
34	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
35	            throws DuplicateIdentityException {
36	        String householdId = OwnerIdentity.householdIdFor(request.getLastName(), request.getPostcode());
37	        String identityKey = OwnerIdentity.key(request.getTelephone(), request.getEmail(), householdId);
38	        boolean sharesHousehold = Boolean.TRUE.equals(request.getSharesHousehold());
39	        for (Owner existing : ownerRepository.findAll()) {
40	            // A soft-deleted owner is not a live duplicate: skip it so its identity/household frees up.
41	            if (existing.isDeleted()) {
42	                continue;
43	            }
44	            if (identityKey.equals(OwnerIdentity.of(existing))) {
45	                throw new DuplicateIdentityException(identityKey);
46	            }
47	            if (!sharesHousehold && householdId != null && householdId.equals(
48	                    OwnerIdentity.householdIdFor(existing.getLastName(), existing.getPostcode()))) {
49	                throw new DuplicateIdentityException(identityKey);
50	            }
51	        }
52	    }
53	}
